int[] arr = {10, 20, 30}; // indices: 0, 1, 2

// These throw ArrayIndexOutOfBoundsException:
arr[3];   // out of bounds — max valid index is 2
arr[-1];  // negative index

// Safe: check bounds
if (i >= 0 && i < arr.length) { System.out.println(arr[i]); }

// Safest: enhanced for loop (no index arithmetic)
for (int val : arr) { System.out.println(val); }
